/** Domain line in the top-right corner, as in the mockups. */
export function PosterDomain() {
  return (
    <p
      aria-hidden="true"
      className={`absolute right-[48px] top-[30px] text-[42px] font-bold leading-none text-white ${handFont.className}`}
    >
      rankingweezer.com
    </p>
  );
}

